package com.cyberrick.phoneinspector.core.model

import com.google.common.truth.Truth.assertThat
import com.google.common.truth.Truth.assertWithMessage
import org.junit.Assert.assertThrows
import org.junit.Test
import java.io.File

/**
 * Phase 3 gate: the evidence model is the contract between collectors, rules and the report.
 * Fixtures under src/test/resources/fixtures are generated by tools/make_fixture.py.
 */
class EvidenceModelTest {
    private val fixtureDir = File(System.getProperty("user.dir") ?: ".", "src/test/resources/fixtures")

    private fun fixture(prefix: String): File =
        fixtureDir
            .listFiles { f -> f.name.startsWith(prefix) && f.extension == "json" }
            ?.singleOrNull()
            ?: error("fixture $prefix* missing in $fixtureDir")

    @Test
    fun `at least sixteen fixtures exist and every one round trips losslessly`() {
        val files = fixtureDir.listFiles { f -> f.extension == "json" }.orEmpty().sortedBy { it.name }
        assertThat(files.size).isAtLeast(16)
        files.forEach { f ->
            val loaded = Evidence.load(f)
            val again = Evidence.fromJson(f.name, loaded.toJson())
            assertWithMessage(f.name).that(again).isEqualTo(loaded)
        }
    }

    @Test
    fun `serialization is deterministic`() {
        val e = Evidence.load(fixture("01_"))
        assertThat(e.toJson()).isEqualTo(Evidence.fromJson("x", e.toJson()).toJson())
    }

    @Test
    fun `a string timestamp is rejected naming the file and the field`() {
        val good = Evidence.load(fixture("01_")).toJson()
        val bad = Regex(""""firstInstallAt":\s*\d+""").replaceFirst(good, "\"firstInstallAt\": \"2026-10-21T10:00:00\"")
        assertThat(bad).isNotEqualTo(good)

        val err = assertThrows(EvidenceParseError::class.java) { Evidence.fromJson("bad_timestamp.json", bad) }

        assertThat(err.message).contains("bad_timestamp.json")
        assertThat(err.message).contains("firstInstallAt")
    }

    @Test
    fun `malformed json names the file`() {
        val err = assertThrows(EvidenceParseError::class.java) { Evidence.fromJson("broken.json", "{ this is not json") }

        assertThat(err.message).contains("broken.json")
    }

    @Test
    fun `unknown json fields are ignored at every level`() {
        val good = Evidence.load(fixture("01_")).toJson()
        val withExtras =
            good
                .replaceFirst("{", "{\"futureTopLevelField\": {\"nested\": [1, 2]},")
                .replaceFirst("\"packageName\"", "\"futureAppField\": true, \"packageName\"")

        val loaded = Evidence.fromJson("extras.json", withExtras)

        assertThat(loaded).isEqualTo(Evidence.load(fixture("01_")))
    }

    @Test
    fun `empty phone fixture loads with zero records and every check status present`() {
        val e = Evidence.load(fixture("13_"))

        assertThat(e.apps).isEmpty()
        assertThat(e.controls).isEmpty()
        assertThat(e.permissions).isEmpty()
        assertThat(e.persistence).isEmpty()
        assertThat(e.flows).isEmpty()
        assertThat(e.checks.map { it.check }).containsExactlyElementsIn(CheckKind.entries)
    }

    @Test
    fun `duplicate package ids are preserved and both flagged`() {
        val e = Evidence.load(fixture("15_"))
        val byPackage = e.apps.groupBy { it.packageName }
        val dupes = byPackage.filterValues { it.size > 1 }

        assertThat(dupes).hasSize(1)
        dupes.values.single().forEach { assertThat(it.duplicate).isTrue() }
        byPackage
            .filterValues { it.size == 1 }
            .values
            .flatten()
            .forEach { assertThat(it.duplicate).isFalse() }
    }

    @Test
    fun `two thousand package fixture loads under 500 ms`() {
        val f = fixture("14_")
        Evidence.load(f) // warm the parser once; the gate is steady state parse time

        val start = System.nanoTime()
        val e = Evidence.load(f)
        val ms = (System.nanoTime() - start) / 1_000_000

        assertThat(e.apps).hasSize(2000)
        assertWithMessage("parse time ms").that(ms).isLessThan(500)
    }

    @Test
    fun `every record carries provenance and a utc epoch timestamp`() {
        val e = Evidence.load(fixture("03_"))
        val all: List<Provenanced> = e.apps + e.controls + e.permissions + e.persistence + e.flows

        assertThat(all).isNotEmpty()
        all.forEach {
            assertThat(it.api).isNotEmpty()
            assertThat(it.collectedAt).isGreaterThan(0L)
        }
        assertThat(e.collectedAt).isGreaterThan(0L)
    }

    @Test
    fun `single element fixture has exactly one app`() {
        assertThat(Evidence.load(fixture("08_")).apps).hasSize(1)
    }
}
